mapper.select:
SELECT r.case_id,r.payment_id,r.reason,r.owner,r.status,r.last_checked_at,r.next_check_at,
  r.resolved_at,r.provider_summary
FROM biz_payment_review_case r JOIN biz_payment p ON p.id=r.payment_id AND NOT p.deleted
WHERE r.status='open'
AND r.case_id > #{after}
ORDER BY r.case_id LIMIT #{limit}
